create extension if not exists pgcrypto;
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind text not null check(kind in('income','expense')),amount numeric(14,2) not null check(amount>0),category text not null,description text,transaction_date date not null default current_date,created_at timestamptz not null default now());
create table if not exists public.debts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,debt_type text not null check(debt_type in('loan','credit_card')),original_balance numeric(14,2) not null default 0,current_balance numeric(14,2) not null default 0,interest_rate numeric(7,4),due_date date,created_at timestamptz not null default now());
create table if not exists public.debt_adjustments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,debt_id uuid not null references public.debts(id) on delete cascade,amount numeric(14,2) not null,note text,created_at timestamptz not null default now());
create table if not exists public.debt_payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,debt_id uuid not null references public.debts(id) on delete cascade,amount numeric(14,2) not null check(amount>0),paid_at date not null default current_date,note text,created_at timestamptz not null default now());
create table if not exists public.payment_allocations(id uuid primary key default gen_random_uuid(),payment_id uuid not null references public.debt_payments(id) on delete cascade,allocation_type text not null check(allocation_type in('principal','interest','fee')),amount numeric(14,2) not null check(amount>=0));
alter table public.transactions enable row level security;alter table public.debts enable row level security;alter table public.debt_adjustments enable row level security;alter table public.debt_payments enable row level security;alter table public.payment_allocations enable row level security;
do $$ declare t text;begin foreach t in array array['transactions','debts','debt_adjustments','debt_payments'] loop execute format('create policy "Users manage own rows" on public.%I for all using (auth.uid()=user_id) with check (auth.uid()=user_id)',t);end loop;end $$;
create policy "Users manage own allocations" on public.payment_allocations for all using(exists(select 1 from public.debt_payments p where p.id=payment_id and p.user_id=auth.uid())) with check(exists(select 1 from public.debt_payments p where p.id=payment_id and p.user_id=auth.uid()));
create or replace function public.record_debt_payment(p_debt_id uuid,p_amount numeric,p_paid_at date default current_date,p_note text default null) returns uuid language plpgsql security invoker as $$declare v_id uuid;begin insert into public.debt_payments(user_id,debt_id,amount,paid_at,note)values(auth.uid(),p_debt_id,p_amount,p_paid_at,p_note)returning id into v_id;update public.debts set current_balance=greatest(0,current_balance-p_amount)where id=p_debt_id and user_id=auth.uid();insert into public.payment_allocations(payment_id,allocation_type,amount)values(v_id,'principal',p_amount);return v_id;end$$;
create or replace function public.record_debt_adjustment(p_debt_id uuid,p_amount numeric,p_note text default null) returns uuid language plpgsql security invoker as $$declare v_id uuid;begin insert into public.debt_adjustments(user_id,debt_id,amount,note)values(auth.uid(),p_debt_id,p_amount,p_note)returning id into v_id;update public.debts set current_balance=greatest(0,current_balance+p_amount)where id=p_debt_id and user_id=auth.uid();return v_id;end$$;
